import RNA, random, multiprocessing as mp, time, sys
target = ".....((.((.((...)).((....))...)))).((.((.((...)).((....))...))))....."
n = len(target)
def fold(s): return RNA.fold_compound(s).mfe()[0]
def worker(seed):
    random.seed(seed)
    best=None;bd=999
    for _ in range(20):
        start=''.join(random.choice('ACGU') for _ in range(n))
        seq,d=RNA.inverse_fold(start,target)
        if d<bd: bd=d;best=seq
        if d==0 and fold(seq)==target:
            return (seq,0)
    return (best,bd)
if __name__=='__main__':
    t0=time.time()
    found=[]
    with mp.Pool(48) as p:
        for r in p.imap_unordered(worker, range(2000)):
            if r[1]==0:
                print("SOLVED",r[0],"time",time.time()-t0);sys.stdout.flush()
                p.terminate();break
        else:
            print("none best",r,"time",time.time()-t0)
